def wet_cells(heights, r, c):
    rows, cols = len(heights), len(heights[0])
    top = heights[r][c]
    seen = {(r, c)}
    stack = [(r, c)]
    while stack:
        i, j = stack.pop()
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < rows and 0 <= b < cols and (a, b) not in seen and heights[a][b] <= top:
                seen.add((a, b))
                stack.append((a, b))
    return len(seen)

